from collections import Counter

class Solution:
    def minDeletions(self, s: str) -> int:
        freqs = sorted(Counter(s).values(), reverse=True)
        deletions = 0
        for i in range(1, len(freqs)):
            if freqs[i] >= freqs[i - 1]:
                target = max(0, freqs[i - 1] - 1)
                deletions += freqs[i] - target
                freqs[i] = target
        return deletions

